      trialTypes: [BUSoftOpenTrialType(label: BULoc(ko: "본인 시범 운영", en: "Owner trial run"), desc: BULoc(ko: "사장 본인이 이용자처럼 입장·결제·기기 사용·퇴장까지 전 과정을 반복 테스트하며 막히는 지점을 기록.", en: "The owner enters, pays, uses the machines, and exits like a real user, repeating the full cycle and logging every friction point.")), BUSoftOpenTrialType(label: BULoc(ko: "지인 첫 이용자", en: "First users (acquaintances)"), desc: BULoc(ko: "가족·지인을 무인 상태로 보내 실제 첫 이용자처럼 행동하게 하고 원격으로 동선을 관찰.", en: "Send family or friends in as real first users with no help, and observe their behavior remotely.")), BUSoftOpenTrialType(label: BULoc(ko: "동네 첫 방문객 관찰", en: "Walk-in observation"), desc: BULoc(ko: "할인·쿠폰으로 유입된 첫 동네 손님이 키오스크 앞에서 헤매는지, 어디서 멈추는지 CCTV로 관찰.", en: "Watch via CCTV how the first discount-driven walk-ins handle the kiosk and where they get stuck.")), BUSoftOpenTrialType(label: BULoc(ko: "원격 모니터링 테스트", en: "Remote monitoring test"), desc: BULoc(ko: "매장을 비운 채 휴대폰 원격 관리 앱으로 결제 로그·CCTV·기기 상태를 실시간 확인.", en: "Leave the store empty and check payment logs, CCTV, and machine status live from the remote management app."))],
      page1Steps: [BUSoftOpenStep(title: BULoc(ko: "무인 결제 흐름 전 과정 테스트", en: "Test the full unmanned payment flow"), detail: BULoc(ko: "키오스크 첫 화면부터 결제 완료까지 1분 안에 끝나는지, 카드·간편결제·환불이 모두 정상인지 직접 여러 번 돌려본다.", en: "Run the kiosk from first screen to completed payment yourself, checking that card, simple-pay, and refunds all work and finish within a minute.")), BUSoftOpenStep(title: BULoc(ko: "첫 이용자 동선 원격 관찰", en: "Observe first users remotely"), detail: BULoc(ko: "매장을 비우고 CCTV·원격앱으로 이용자가 어디서 헤매는지 보고, 안내문·동선 표시가 부족한 곳을 보완.", en: "Empty the store and use CCTV and the remote app to see where users hesitate, then add signage or fix the layout where guidance is missing.")), BUSoftOpenStep(title: BULoc(ko: "무인 장애 대응 시나리오 점검", en: "Check failure-response scenarios"), detail: BULoc(ko: "기기 오류·결제 실패·문 안 열림 상황에서 비상연락·원격제어·환불이 즉시 되는지 미리 시연.", en: "Simulate machine errors, failed payments, and a stuck door to confirm the emergency contact, remote control, and refund all respond instantly."))],
      feedbackAxes: [BUSoftOpenItem(label: BULoc(ko: "키오스크·결제 편의성", en: "Kiosk & payment ease"), detail: BULoc(ko: "안내 없이도 첫 이용자가 결제까지 막힘없이 끝내는가. 실패 로그·문의가 없는지 확인.", en: "Can a first-time user complete payment without help and with no failure logs or inquiries.")), BUSoftOpenItem(label: BULoc(ko: "청결·정돈 상태", en: "Cleanliness & order"), detail: BULoc(ko: "무인이라 방치되기 쉬운 바닥·쓰레기·소모품 보충 상태가 종일 유지되는가.", en: "Floors, trash, and supply refills stay maintained all day despite no on-site staff.")), BUSoftOpenItem(label: BULoc(ko: "기기·설비 안정성", en: "Machine & equipment reliability"), detail: BULoc(ko: "세탁기·커피머신·운동기구 등 핵심 기기가 멈추거나 오작동 없이 연속 가동되는가.", en: "Core machines run continuously without stopping or malfunctioning.")), BUSoftOpenItem(label: BULoc(ko: "보안·안전 체감", en: "Security & safety"), detail: BULoc(ko: "CCTV·비상벨·출입통제가 작동하고 이용자가 야간에도 안전하다고 느끼는가.", en: "CCTV, emergency bell, and access control work, and users feel safe even at night."))],
      finalPrep: [BUSoftOpenItem(label: BULoc(ko: "소모품 재고 채우기", en: "Stock consumables"), detail: BULoc(ko: "세제·유연제·컵·용지·세정제 등 무인 소모품을 본오픈 전 충분히 확보·자동투입 점검.", en: "Secure ample detergent, softener, cups, paper, and cleaning supplies, and verify auto-dispensing before launch.")), BUSoftOpenItem(label: BULoc(ko: "키오스크·결제 최종 점검", en: "Final kiosk & payment check"), detail: BULoc(ko: "가격·메뉴 세팅 확정, 결제 단말 정산·영수증·환불 모두 재검증.", en: "Finalize price and menu setup and re-verify settlement, receipts, and refunds on the payment terminal.")), BUSoftOpenItem(label: BULoc(ko: "CCTV·녹화 보존 확인", en: "Confirm CCTV recording"), detail: BULoc(ko: "전 구역 사각지대 없이 녹화되고 저장 기간·원격 열람이 정상인지 최종 확인.", en: "Confirm full-coverage recording with no blind spots and that retention period and remote access work.")), BUSoftOpenItem(label: BULoc(ko: "원격 관리 체계 확정", en: "Finalize remote management"), detail: BULoc(ko: "기기 상태 알림·원격 제어·비상연락 동선을 본오픈 운영 기준으로 고정.", en: "Lock in machine-status alerts, remote control, and emergency contact routing for live operation.")), BUSoftOpenItem(label: BULoc(ko: "청소·점검 루틴 확정", en: "Lock in cleaning routine"), detail: BULoc(ko: "무인 매장의 일·주 단위 방문 청소·소모품 보충·점검 주기를 정해 캘린더화.", en: "Set and calendar the daily/weekly visit cycle for cleaning, restocking, and inspection."))]),
    "beauty-svc": BUSoftOpenContent(
      softOpenMeaning: BULoc(ko: "뷰티·시술업의 소프트오픈은 정식 개업 전 모델·체험 고객에게 할인 또는 무료로 시술해 손기술·동선·예약 흐름을 점검하고, 결과물 사진과 후기를 쌓아 첫 단골을 확보하는 기간이다.", en: "For beauty and treatment businesses, a soft open is a pre-launch window where you serve model and trial clients at a discount or free, testing your technique, workflow and booking flow while building a portfolio of result photos and reviews to win your first regulars."), page1Label: BULoc(ko: "1. 체험 예약", en: "1. Trial Bookings"), pricingMode: "price", pricingAlt: nil,
      trialTypes: [BUSoftOpenTrialType(label: BULoc(ko: "모델 시술 고객", en: "Model clients"), desc: BULoc(ko: "무료 또는 큰 할인으로 시술하고 결과 사진·후기 사용에 동의받는 고객. 포트폴리오와 SNS 콘텐츠 확보용.", en: "Clients served free or deeply discounted who consent to result photos and reviews, used to build your portfolio and social content.")), BUSoftOpenTrialType(label: BULoc(ko: "지인·인근 상인", en: "Acquaintances & nearby shop owners"), desc: BULoc(ko: "솔직한 피드백을 줄 수 있는 지인과 같은 건물·골목 상인. 동선과 응대 점검에 적합.", en: "Friends and neighboring merchants who give honest feedback, ideal for testing flow and service.")), BUSoftOpenTrialType(label: BULoc(ko: "첫 방문 할인 고객", en: "First-visit discount clients"), desc: BULoc(ko: "오픈 할인을 보고 예약한 신규 고객. 실제 가격 민감도와 재방문 의향을 본다.", en: "New clients booking via your opening discount, to gauge real price sensitivity and rebooking intent.")), BUSoftOpenTrialType(label: BULoc(ko: "체험단·리뷰어", en: "Reviewers & trial groups"), desc: BULoc(ko: "네이버 플레이스·인스타 후기를 남기는 체험단. 초기 검색 노출과 신뢰도 확보용.", en: "Trial-group members who post Naver Place or Instagram reviews to build early search visibility and trust."))],
      page1Steps: [BUSoftOpenStep(title: BULoc(ko: "모델·체험 예약 8~12건 채우기", en: "Fill 8-12 model/trial bookings"), detail: BULoc(ko: "개업 전 며칠에 걸쳐 시간대를 분산해 예약을 잡는다. 시술 시간이 길므로 하루 처리량을 실제로 측정한다.", en: "Spread bookings across several pre-launch days and time slots. Treatments run long, so measure your real daily capacity.")), BUSoftOpenStep(title: BULoc(ko: "안전 테스트·문진 절차 가동", en: "Run safety tests and intake form"), detail: BULoc(ko: "패치테스트·스킨테스트, 알러지·시술 이력 문진표를 첫 고객부터 적용해 부작용을 차단한다.", en: "Apply patch/skin tests and an allergy/history intake form from the first client to prevent adverse reactions.")), BUSoftOpenStep(title: BULoc(ko: "예약·결제·동의 흐름 한 바퀴 돌리기", en: "Run the full booking-to-payment loop"), detail: BULoc(ko: "예약 앱 알림 → 시술 → 사진 동의 → 결제 → 재예약 권유까지 빈틈 없이 한 번씩 실행한다.", en: "Walk the entire loop once: booking app reminder, treatment, photo consent, payment, and rebooking prompt."))],
      feedbackAxes: [BUSoftOpenItem(label: BULoc(ko: "시술 결과 만족도", en: "Result satisfaction"), detail: BULoc(ko: "마감 완성도·지속력·디자인 만족을 고객 표정과 한 줄 후기로 확인한다.", en: "Check finish quality, durability and design satisfaction via the client's reaction and a one-line review.")), BUSoftOpenItem(label: BULoc(ko: "소요 시간·대기", en: "Treatment time & waiting"), detail: BULoc(ko: "예약 간격이 현실적인지, 지연·대기가 생기는지 측정해 본오픈 예약 슬롯을 조정한다.", en: "Measure whether slot spacing is realistic and where delays occur, then adjust launch-day booking slots.")), BUSoftOpenItem(label: BULoc(ko: "위생·청결 체감", en: "Perceived hygiene"), detail: BULoc(ko: "소독된 기구, 일회용품 교체, 침대·수건 청결을 고객이 눈으로 신뢰하는지 본다.", en: "See whether clients visibly trust your sterilized tools, single-use swaps, and clean beds and towels.")), BUSoftOpenItem(label: BULoc(ko: "응대·상담", en: "Service & consultation"), detail: BULoc(ko: "시술 전 상담, 사후 관리 안내, 재예약 권유가 부담 없이 전달되는지 점검한다.", en: "Check that pre-consultation, aftercare guidance and rebooking suggestions feel natural, not pushy."))],
      finalPrep: [BUSoftOpenItem(label: BULoc(ko: "제품·소모품 재고 확정", en: "Lock product & consumable stock"), detail: BULoc(ko: "왁스·글루·폴리시·관리제품과 일회용 스파출라·면봉·장갑 재고를 회전량 기준으로 확보한다.", en: "Secure wax, glue, polish, care products and single-use spatulas, swabs and gloves based on real turnover.")), BUSoftOpenItem(label: BULoc(ko: "예약 슬롯·메뉴·가격표 확정", en: "Finalize slots, menu & price list"), detail: BULoc(ko: "시범에서 측정한 실제 소요 시간으로 예약 간격을 정하고 정가 메뉴판을 확정한다.", en: "Set slot spacing from measured treatment times and finalize your standard-price menu.")), BUSoftOpenItem(label: BULoc(ko: "위생·소독 루틴 표준화", en: "Standardize hygiene routine"), detail: BULoc(ko: "소독기·자외선 살균, 일회용 교체 주기, 침대 커버 교체를 체크리스트로 고정한다.", en: "Fix sterilizer/UV cycles, single-use swap intervals and bed-cover changes into a checklist.")), BUSoftOpenItem(label: BULoc(ko: "후기·포트폴리오 게시", en: "Publish reviews & portfolio"), detail: BULoc(ko: "시범에서 모은 결과 사진과 후기를 네이버 플레이스·인스타에 올려 검색 노출을 만든다.", en: "Post result photos and reviews from the trial to Naver Place and Instagram to build search visibility.")), BUSoftOpenItem(label: BULoc(ko: "기기·전기·환기 최종 점검", en: "Final equipment & ventilation check"), detail: BULoc(ko: "관리기기·왁스워머·환풍 시설을 정상 가동 확인하고 비상 키트(화상·알러지)를 비치한다.", en: "Confirm machines, wax warmers and ventilation run properly and stock an emergency kit (burns/allergy)."))]),
    "fitness-class": BUSoftOpenContent(
      softOpenMeaning: BULoc(ko: "무료·할인 체험 수업이나 시범 클래스를 열어 실제 회원을 받아보며 강사 진행, 수업 정원·동선, 기구·시설 안전을 본오픈 전에 점검하는 기간이다.", en: "A trial period running free or discounted demo classes with real members to test instructor delivery, class scheduling and flow, and equipment/facility safety before the full opening."), page1Label: BULoc(ko: "1. 체험 수업 모집", en: "1. Recruit Trial Classes"), pricingMode: "price", pricingAlt: nil,
      trialTypes: [BUSoftOpenTrialType(label: BULoc(ko: "동네 첫 체험 회원", en: "Local First-Trial Members"), desc: BULoc(ko: "전단·SNS로 모은 인근 거주자. 무료/할인 1회 체험으로 시설·수업을 직접 경험", en: "Nearby residents gathered via flyers/SNS for a free or discounted single trial of the facility and class")), BUSoftOpenTrialType(label: BULoc(ko: "기존 운동 경험자", en: "Experienced Exercisers"), desc: BULoc(ko: "타 스튜디오·헬스장 경험자. 강사 수준과 시설을 비교 평가해줄 핵심 피드백 그룹", en: "People from other studios/gyms who can critically compare instructor quality and facilities")), BUSoftOpenTrialType(label: BULoc(ko: "지인·강사 네트워크", en: "Acquaintance / Instructor Network"), desc: BULoc(ko: "강사 지인·소개. 정원 채우기와 수업 분위기 형성에 도움, 솔직한 진행 피드백", en: "Instructor referrals to fill class capacity, build atmosphere, and give honest delivery feedback")), BUSoftOpenTrialType(label: BULoc(ko: "오픈 이벤트 사전등록자", en: "Pre-Registration Sign-Ups"), desc: BULoc(ko: "플레이스·온라인으로 사전 등록한 잠재 회원. 본오픈 정식 등록 전환 1순위", en: "Potential members who pre-registered online/Place; top candidates to convert at full opening"))],
      page1Steps: [BUSoftOpenStep(title: BULoc(ko: "체험 수업 시간표 확정", en: "Set Trial Class Schedule"), detail: BULoc(ko: "요일·시간대별 시범 클래스를 정하고 정원을 작게 잡아 예약 프로그램(스튜디오메이트 등)에 등록", en: "Fix demo class slots by day/time with small capacity and register them in your booking app (e.g. StudioMate)")), BUSoftOpenStep(title: BULoc(ko: "체험가·전환 혜택 설계", en: "Design Trial Price & Conversion Offer"), detail: BULoc(ko: "무료 또는 1만~2만원 체험가 책정, 본오픈 등록 시 할인되는 전환 혜택을 함께 안내", en: "Set a free or 10,000–20,000 KRW trial price plus a discount offer for members who sign up at full opening")), BUSoftOpenStep(title: BULoc(ko: "강사 진행 리허설", en: "Instructor Run-Through"), detail: BULoc(ko: "실제 정원으로 한 타임을 끝까지 진행해 멘트·동작 시연·시간 배분·안전 안내를 점검", en: "Run one full class at real capacity to check cueing, demos, time pacing, and safety briefing"))],
      feedbackAxes: [BUSoftOpenItem(label: BULoc(ko: "강사 수업 만족도", en: "Instructor / Class Quality"), detail: BULoc(ko: "설명 명확성, 동작 교정, 난이도 적정성, 다음에도 듣고 싶은지", en: "Clarity of cues, form correction, appropriate difficulty, willingness to return")), BUSoftOpenItem(label: BULoc(ko: "시설·청결", en: "Facility & Cleanliness"), detail: BULoc(ko: "매트·기구 청결, 탈의실·샤워실, 환기·온습도, 공간 여유", en: "Mat/equipment cleanliness, changing/shower rooms, ventilation/temperature, space comfort")), BUSoftOpenItem(label: BULoc(ko: "예약·결제 편의", en: "Booking & Payment Ease"), detail: BULoc(ko: "앱 예약·취소, 입장 확인, 결제·수강권 안내가 매끄러웠는지", en: "App booking/cancel, check-in, and payment/pass guidance ran smoothly")), BUSoftOpenItem(label: BULoc(ko: "수업 정원·동선", en: "Class Capacity & Flow"), detail: BULoc(ko: "정원 대비 공간, 기구 대기, 수업 교체 시 혼잡 여부", en: "Space per capacity, equipment wait, congestion during class turnover"))],
      finalPrep: [BUSoftOpenItem(label: BULoc(ko: "기구·시설 안전 최종 점검", en: "Final Equipment & Safety Check"), detail: BULoc(ko: "리포머 스프링·바벨 잠금·머신 볼트·바닥 하중 등 안전요소를 본오픈 전 전수 점검", en: "Inspect reformer springs, barbell collars, machine bolts, floor load and all safety items before opening")), BUSoftOpenItem(label: BULoc(ko: "수강권·결제 시스템 세팅", en: "Membership & Payment Setup"), detail: BULoc(ko: "회차권·기간권·PT패키지 등 수강권 상품과 결제·환불 정책을 예약 프로그램에 등록", en: "Register passes (session/term/PT packages) and payment/refund policy in the booking system")), BUSoftOpenItem(label: BULoc(ko: "정식 시간표·강사 배치 확정", en: "Finalize Schedule & Instructor Roster"), detail: BULoc(ko: "체험 피드백을 반영해 인기 시간대·강사 배치를 조정하고 본오픈 주간 시간표 공지", en: "Adjust popular slots and instructor assignments from trial feedback; publish the opening-week schedule")), BUSoftOpenItem(label: BULoc(ko: "소모품·비품 재고 확보", en: "Stock Consumables & Supplies"), detail: BULoc(ko: "기구 소독제·수건·생수·일회용 양말·청소용품 등 운영 소모품을 본오픈 물량으로 확보", en: "Secure operating consumables: equipment sanitizer, towels, water, grip socks, cleaning supplies")), BUSoftOpenItem(label: BULoc(ko: "AED·응급 대응 준비", en: "AED & Emergency Readiness"), detail: BULoc(ko: "AED 위치·작동·패드 유효기간 확인, 응급 연락망과 직원 심정지 대응 절차 숙지", en: "Verify AED location/operation/pad expiry; confirm emergency contacts and staff cardiac-response steps"))]),
    "academy": BUSoftOpenContent(
      softOpenMeaning: BULoc(ko: "학원에서 소프트오픈은 정식 개강 전에 소수 인원으로 시범 수업과 오리엔테이션을 돌려보며 수업 흐름·강사 진행·동선·안전을 검증하는 단계입니다. 학생과 학부모의 반응을 보고 수업 구성과 운영을 다듬은 뒤 정식 개강합니다.", en: "For an academy, soft open means running trial lessons and orientations with a small group before the official term starts, to verify lesson flow, instructor delivery, student movement, and safety. You refine the program based on student and parent feedback, then open the full term."), page1Label: BULoc(ko: "1. 시범 수업", en: "1. Trial Lesson"), pricingMode: "price", pricingAlt: nil,
      trialTypes: [BUSoftOpenTrialType(label: BULoc(ko: "무료 체험 수업생", en: "Free trial students"), desc: BULoc(ko: "1~2회 무료 체험으로 수업을 경험하게 하고 등록 전환을 노리는 핵심 유치 대상", en: "Let prospects experience 1-2 free sessions to drive enrollment conversion")), BUSoftOpenTrialType(label: BULoc(ko: "학부모 참관·설명회", en: "Parent observation & info session"), desc: BULoc(ko: "학부모를 초대해 커리큘럼·안전·강사를 직접 보여주고 신뢰를 쌓는 대상", en: "Invite parents to see curriculum, safety, and instructors firsthand to build trust")), BUSoftOpenTrialType(label: BULoc(ko: "지인·소개 등록생", en: "Referral students"), desc: BULoc(ko: "기존 인맥·동네 소개로 들어온 초기 정원, 입소문의 시작점", en: "Early seats from personal and neighborhood referrals, the start of word of mouth")), BUSoftOpenTrialType(label: BULoc(ko: "오픈 할인 선등록생", en: "Open-discount pre-enrollees"), desc: BULoc(ko: "개강 전 할인 조건으로 먼저 등록하는 학생, 초기 캐시플로 확보", en: "Students who pre-enroll at an opening discount, securing early cash flow"))],
      page1Steps: [BUSoftOpenStep(title: BULoc(ko: "시범 수업 1타임 운영", en: "Run one trial lesson slot"), detail: BULoc(ko: "실제 정원 규모로 한 타임을 처음부터 끝까지 진행해 도입·전개·마무리 시간 배분과 학생 집중도를 점검한다", en: "Run one full slot at real class size to check pacing of intro/core/wrap-up and student focus")), BUSoftOpenStep(title: BULoc(ko: "오리엔테이션·학부모 안내", en: "Orientation & parent briefing"), detail: BULoc(ko: "수업 목표·진도·준비물·등하원 규칙·안전 동선을 학생과 학부모에게 설명하고 질문을 받는다", en: "Explain lesson goals, schedule, materials, pickup rules, and safety routes to students and parents, then take questions")), BUSoftOpenStep(title: BULoc(ko: "등록·결제 흐름 테스트", en: "Test enrollment & payment flow"), detail: BULoc(ko: "상담→등록서 작성→수강료 결제→교재 지급까지 한 명을 끝까지 통과시켜 누락 단계를 찾는다", en: "Walk one student end to end through consult, enrollment form, tuition payment, and material handout to find gaps"))],
      feedbackAxes: [BUSoftOpenItem(label: BULoc(ko: "수업 이해도·난이도", en: "Comprehension & difficulty"), detail: BULoc(ko: "학생이 진도를 따라오는지, 너무 쉽거나 어렵지 않은지 수준 적정성을 확인", en: "Check whether students keep up and whether the level is too easy or too hard")), BUSoftOpenItem(label: BULoc(ko: "강사 진행·전달력", en: "Instructor delivery"), detail: BULoc(ko: "설명이 명확한지, 학생 통제와 호응 유도가 자연스러운지 평가", en: "Assess clarity of explanation and how naturally the instructor manages and engages students")), BUSoftOpenItem(label: BULoc(ko: "학부모 만족·신뢰", en: "Parent satisfaction & trust"), detail: BULoc(ko: "안전·소통·결과 기대에 대한 학부모 반응과 재등록 의향을 확인", en: "Gauge parent reactions on safety, communication, and results, plus re-enrollment intent")), BUSoftOpenItem(label: BULoc(ko: "시설·동선·안전", en: "Facility, flow & safety"), detail: BULoc(ko: "교실 환경·소음·등하원 동선·비상 대피가 실제로 문제없는지 점검", en: "Check classroom environment, noise, pickup flow, and emergency evacuation in practice"))],
      finalPrep: [BUSoftOpenItem(label: BULoc(ko: "교재·교구 재고 확보", en: "Stock textbooks & teaching tools"), detail: BULoc(ko: "정식 개강 정원에 맞춰 교재·워크북·교구·소모품(프린트·필기구) 수량을 확보한다", en: "Secure textbooks, workbooks, teaching tools, and consumables for the full opening headcount")), BUSoftOpenItem(label: BULoc(ko: "시간표·반편성 확정", en: "Finalize timetable & class sections"), detail: BULoc(ko: "레벨·요일별 시간표와 반 정원, 강사 배정을 확정해 충돌·과밀을 제거한다", en: "Lock the level/day timetable, class sizes, and instructor assignments to remove conflicts and overcrowding")), BUSoftOpenItem(label: BULoc(ko: "등록·수납 시스템 점검", en: "Verify enrollment & billing system"), detail: BULoc(ko: "학원관리 프로그램에 학생·수강료·결제수단을 등록하고 영수증·환불 규정을 정비한다", en: "Register students, tuition, and payment methods in the academy management system; set receipt and refund rules")), BUSoftOpenItem(label: BULoc(ko: "소방·안전 설비 확인", en: "Check fire & safety equipment"), detail: BULoc(ko: "소화기·비상구·완강기·CCTV 작동과 학원 인허가·소방완비증명을 최종 확인한다", en: "Confirm extinguishers, exits, descent devices, CCTV, and that the academy license and fire-safety certificate are in order")), BUSoftOpenItem(label: BULoc(ko: "강사 운영·비상 매뉴얼 공유", en: "Share instructor & emergency manual"), detail: BULoc(ko: "강사에게 수업 운영·출결·학부모 응대·비상 대피 절차를 사전 교육한다", en: "Pre-train instructors on lesson operations, attendance, parent handling, and emergency evacuation procedures"))]),
    "pet-svc": BUSoftOpenContent(
      softOpenMeaning: BULoc(ko: "펫 서비스 가오픈은 소수의 반려동물·보호자를 시범 예약으로 받아 실제 케어 흐름(접수→케어→인계)과 동물 안전·위생을 점검하는 기간이다. 본오픈 전 동선·예약·응급 대응의 빈틈을 찾아 보호자 신뢰를 확보한다.", en: "For pet services, a soft open means taking a few pets and owners as trial bookings to test the real care flow (intake to care to handover) and verify animal safety and hygiene. It surfaces gaps in flow, booking, and emergency response before full launch and builds owner trust."), page1Label: BULoc(ko: "1. 시범 예약", en: "1. Trial Bookings"), pricingMode: "price", pricingAlt: nil,
      trialTypes: [BUSoftOpenTrialType(label: BULoc(ko: "지인·이웃 반려인", en: "Friends and neighbor pet owners"), desc: BULoc(ko: "믿을 수 있는 지인의 반려동물을 먼저 받아 케어 흐름과 동물 반응을 부담 없이 점검한다.", en: "Take pets of trusted acquaintances first to test the care flow and animal reactions with low pressure.")), BUSoftOpenTrialType(label: BULoc(ko: "동네 단골 후보", en: "Local regular candidates"), desc: BULoc(ko: "반복 방문 가능성이 높은 인근 거주 반려인을 시범 예약으로 유치해 재방문 의향을 확인한다.", en: "Bring in nearby owners likely to return as trial bookings and check their intent to come back.")), BUSoftOpenTrialType(label: BULoc(ko: "온라인 카페·SNS 반응자", en: "Online community and SNS responders"), desc: BULoc(ko: "지역 맘카페·반려견 모임에 시범 예약을 알리고 신청한 보호자를 받아 홍보 채널을 검증한다.", en: "Announce trial bookings in local communities and dog meetups, take applicants, and validate promo channels.")), BUSoftOpenTrialType(label: BULoc(ko: "민감·특수 케이스 1건", en: "One sensitive or special case"), desc: BULoc(ko: "노령견·예민견 등 까다로운 케이스를 한 건 받아 응급·돌발 상황 대응력을 미리 점검한다.", en: "Take one tricky case such as a senior or anxious pet to test emergency and incident response in advance."))],
      page1Steps: [BUSoftOpenStep(title: BULoc(ko: "시범 예약 5~8건 받기", en: "Take 5 to 8 trial bookings"), detail: BULoc(ko: "시간대를 분산해 예약을 받아 접수·대기·인계 동선과 예약 시스템이 실제로 돌아가는지 확인한다.", en: "Spread bookings across time slots to confirm the intake, waiting, and handover flow and that the booking system actually works.")), BUSoftOpenStep(title: BULoc(ko: "동물 정보·동의서 사전 접수", en: "Collect pet info and consent forms upfront"), detail: BULoc(ko: "품종·나이·접종·기저질환·특이행동을 미리 받고 위탁/케어 동의서를 받아 사고 리스크를 줄인다.", en: "Gather breed, age, vaccination, conditions, and behavior notes upfront and obtain a care or custody consent to reduce incident risk.")), BUSoftOpenStep(title: BULoc(ko: "안전·위생 1차 가동 점검", en: "First run of safety and hygiene"), detail: BULoc(ko: "바닥 미끄럼·탈출 동선·소독·환기를 실제 동물이 있는 상태에서 점검하고 응급 동물병원 연락처를 비치한다.", en: "Check slip floors, escape routes, disinfection, and ventilation with real animals present, and post the emergency vet contact."))],
      feedbackAxes: [BUSoftOpenItem(label: BULoc(ko: "케어 결과 만족", en: "Care result satisfaction"), detail: BULoc(ko: "미용 마감·돌봄 상태·훈련 변화 등 결과물에 보호자가 만족하는지, 기대와 어긋난 점은 없는지 확인한다.", en: "Check whether owners are satisfied with the result such as grooming finish, care condition, or training change, and any gaps from expectations.")), BUSoftOpenItem(label: BULoc(ko: "동물 안전·스트레스", en: "Animal safety and stress"), detail: BULoc(ko: "케어 중 동물이 다치거나 과도하게 불안해하지 않았는지, 합사·대기 환경이 안전했는지 점검한다.", en: "Check whether animals were injured or overly stressed during care, and whether grouping and waiting areas were safe.")), BUSoftOpenItem(label: BULoc(ko: "위생·냄새·청결", en: "Hygiene, odor, cleanliness"), detail: BULoc(ko: "배변 처리·소독·환기로 냄새와 위생 상태가 보호자가 안심할 수준인지 확인한다.", en: "Confirm that waste handling, disinfection, and ventilation keep odor and hygiene at a level owners find reassuring.")), BUSoftOpenItem(label: BULoc(ko: "소통·인계 신뢰", en: "Communication and handover trust"), detail: BULoc(ko: "케어 일지·사진·인계 설명이 충분했는지, 보호자가 맡기는 데 신뢰가 생겼는지 확인한다.", en: "Confirm whether care logs, photos, and handover explanations were sufficient and built owner trust in leaving the pet."))],
      finalPrep: [BUSoftOpenItem(label: BULoc(ko: "소모품·케어용품 재고 확인", en: "Stock care supplies and consumables"), detail: BULoc(ko: "샴푸·소독제·배변패드·사료·간식 등 소모품 재고와 발주처를 본오픈 수요에 맞게 확보한다.", en: "Secure stock and suppliers of shampoo, disinfectant, pee pads, food, and treats to match full-launch demand.")), BUSoftOpenItem(label: BULoc(ko: "예약·결제 시스템 정비", en: "Finalize booking and payment"), detail: BULoc(ko: "예약 채널·노쇼 정책·결제 수단을 점검하고 시간대별 수용 인원을 확정한다.", en: "Check booking channels, no-show policy, and payment methods, and fix the capacity per time slot.")), BUSoftOpenItem(label: BULoc(ko: "동물 안전·시설 최종 점검", en: "Final animal safety and facility check"), detail: BULoc(ko: "미끄럼·탈출·합사 위험과 냉난방·환기를 최종 점검하고 응급 동물병원 협력 체계를 확정한다.", en: "Final-check slip, escape, and grouping risks plus heating and ventilation, and confirm the emergency vet partnership.")), BUSoftOpenItem(label: BULoc(ko: "가격·서비스 메뉴 확정", en: "Finalize pricing and service menu"), detail: BULoc(ko: "체중·견종·시간별 요금표와 추가 옵션을 확정하고 보호자가 보기 쉽게 게시한다.", en: "Finalize the price table by weight, breed, or time plus add-on options and post it clearly for owners.")), BUSoftOpenItem(label: BULoc(ko: "보험·동의서·기록 체계 구축", en: "Set up insurance, consent, and records"), detail: BULoc(ko: "배상책임보험과 위탁·케어 동의서, 동물별 기록 양식을 갖춰 사고 시 책임 체계를 마련한다.", en: "Set up liability insurance, custody and care consent forms, and per-animal record templates to cover incident accountability."))]),
    "retail-store": BUSoftOpenContent(
      softOpenMeaning: BULoc(ko: "리테일 매장의 소프트 오픈은 정식 오픈 전 매장을 실제로 열어 진열·재고·POS·동선을 점검하고, 첫 손님의 구매·결제 흐름을 관찰하며 문제를 미리 보완하는 시범 운영 기간입니다.", en: "For a retail store, a soft open is a trial-run period before grand opening where you actually open the store to check displays, inventory, POS, and customer flow, observing how first shoppers browse and check out so you can fix issues in advance."), page1Label: BULoc(ko: "1. 첫 손님 맞이", en: "1. First Shoppers"), pricingMode: "price", pricingAlt: nil,
      trialTypes: [BUSoftOpenTrialType(label: BULoc(ko: "동네 첫 손님", en: "Local first shoppers"), desc: BULoc(ko: "지나가다 들른 인근 주민. 매장 인지도와 첫인상, 진열 동선이 잘 통하는지 관찰합니다.", en: "Neighborhood residents who drop in. Observe first impressions, store awareness, and whether the display flow works.")), BUSoftOpenTrialType(label: BULoc(ko: "지인·단골 후보", en: "Acquaintances & regular candidates"), desc: BULoc(ko: "솔직한 피드백을 줄 지인. 가격표·결제·품목 구성에 대해 가감 없이 의견을 받습니다.", en: "Acquaintances who give honest feedback on price tags, checkout, and product mix.")), BUSoftOpenTrialType(label: BULoc(ko: "온라인 유입 손님", en: "Online-driven visitors"), desc: BULoc(ko: "SNS·지도 보고 찾아온 손님. 온라인 정보와 실제 매장이 일치하는지, 재방문 의향을 확인합니다.", en: "Visitors who found you via SNS or maps. Check that online info matches the real store and gauge return intent.")), BUSoftOpenTrialType(label: BULoc(ko: "구매 안 한 둘러보기 손님", en: "Browse-only visitors"), desc: BULoc(ko: "구경만 하고 나간 손님. 왜 구매로 이어지지 않았는지(가격·구색·진열) 관찰 포인트입니다.", en: "Visitors who browsed but didn't buy. A key signal for why browsing didn't convert—price, assortment, or display."))],
      page1Steps: [BUSoftOpenStep(title: BULoc(ko: "오픈 안내·첫 손님 동선 점검", en: "Announce opening & check first-shopper flow"), detail: BULoc(ko: "입구 안내문과 영업시간을 게시하고, 손님이 들어와 둘러보고 계산대까지 가는 동선이 막힘없는지 직접 따라가며 확인합니다.", en: "Post entrance signage and hours, then walk the path a shopper takes from entry through browsing to the checkout to confirm it flows without bottlenecks.")), BUSoftOpenStep(title: BULoc(ko: "POS·결제 실거래 테스트", en: "Test POS and live payment"), detail: BULoc(ko: "실제 손님 결제로 카드·간편결제·현금영수증·바코드 스캔이 정상 작동하는지 확인하고, 계산 속도와 잔돈 준비를 점검합니다.", en: "Confirm card, easy-pay, cash receipts, and barcode scanning all work with real transactions; check checkout speed and change float.")), BUSoftOpenStep(title: BULoc(ko: "첫 구매·미구매 반응 관찰", en: "Observe buy vs. no-buy reactions"), detail: BULoc(ko: "어떤 품목 앞에 손님이 멈추고, 무엇을 집었다 놓는지, 구매로 이어지지 않은 이유를 메모해 진열·구색을 즉시 보완합니다.", en: "Note where shoppers stop, what they pick up and put back, and why browsing didn't convert—then adjust display and assortment right away."))],
      feedbackAxes: [BUSoftOpenItem(label: BULoc(ko: "진열·찾기 쉬움", en: "Display & findability"), detail: BULoc(ko: "원하는 상품을 쉽게 찾았는지, 진열이 보기 좋고 가격표가 명확했는지.", en: "Whether shoppers easily found what they wanted, and whether displays looked good with clear price tags.")), BUSoftOpenItem(label: BULoc(ko: "상품 구색·가격", en: "Assortment & price"), detail: BULoc(ko: "찾던 품목이 있었는지, 가격이 적정하게 느껴졌는지, 빠진 인기 품목은 없는지.", en: "Whether the items shoppers wanted were stocked, prices felt fair, and no popular items were missing.")), BUSoftOpenItem(label: BULoc(ko: "결제 편의·속도", en: "Checkout convenience & speed"), detail: BULoc(ko: "원하는 결제수단이 됐는지, 대기·계산이 빠르고 매끄러웠는지.", en: "Whether the desired payment method worked and checkout was fast and smooth without waiting.")), BUSoftOpenItem(label: BULoc(ko: "응대·매장 분위기", en: "Service & store atmosphere"), detail: BULoc(ko: "문의 응대가 친절·정확했는지, 조명·음악·청결 등 매장 분위기가 좋았는지.", en: "Whether inquiries were answered helpfully and accurately, and lighting, music, and cleanliness felt good."))],
      finalPrep: [BUSoftOpenItem(label: BULoc(ko: "재고·구색 보충", en: "Restock & assortment fill"), detail: BULoc(ko: "시범 운영에서 잘 나간 품목과 빠진 인기 품목을 반영해 정식 오픈 전 발주·재고를 채웁니다.", en: "Reorder and restock before grand opening, reflecting best-sellers and any missing popular items found during the trial.")), BUSoftOpenItem(label: BULoc(ko: "진열·가격표 정비", en: "Finalize display & price tags"), detail: BULoc(ko: "관찰한 손님 동선에 맞춰 진열을 재배치하고, 모든 품목의 가격표·바코드를 빠짐없이 정비합니다.", en: "Rearrange displays to match observed shopper flow and ensure every item has a correct price tag and barcode.")), BUSoftOpenItem(label: BULoc(ko: "POS·결제수단 최종 점검", en: "Final POS & payment check"), detail: BULoc(ko: "카드·간편결제·현금영수증·재고 연동이 모두 정상인지 재확인하고 잔돈을 충분히 준비합니다.", en: "Re-verify card, easy-pay, cash receipts, and inventory sync all work; prepare an adequate change float.")), BUSoftOpenItem(label: BULoc(ko: "오픈 홍보·지도 등록", en: "Promotion & map listing"), detail: BULoc(ko: "네이버 플레이스·SNS에 오픈 일정과 사진을 올리고, 영업시간·위치 정보가 실제와 일치하는지 확인합니다.", en: "Post opening date and photos on map and SNS, confirming hours and location info match the real store.")), BUSoftOpenItem(label: BULoc(ko: "운영 동선·역할 정리", en: "Operations flow & roles"), detail: BULoc(ko: "오픈·마감 체크리스트와 직원 역할(계산·진열·응대)을 정리해 정식 오픈 첫날 혼선을 줄입니다.", en: "Finalize open/close checklists and staff roles (checkout, restocking, service) to reduce confusion on day one."))]),
    "visit-svc": BUSoftOpenContent(
      softOpenMeaning: BULoc(ko: "소프트오픈은 정식 영업 전 소수의 시범 고객에게 실제 서비스를 제공하며 작업 동선·접수·견적·결과 품질을 점검하는 기간이다. 클레임 없이 본오픈하기 위한 마지막 리허설이다.", en: "A soft open is a trial period where you serve a few pilot customers with real service to test your workflow, intake, quotes, and result quality. It's the final rehearsal before opening for real, claim-free."), page1Label: BULoc(ko: "1. 시범 고객", en: "1. Pilot Customers"), pricingMode: "price", pricingAlt: nil,
      trialTypes: [BUSoftOpenTrialType(label: BULoc(ko: "지인·가족", en: "Friends & family"), desc: BULoc(ko: "부담 없이 솔직한 피드백을 줄 수 있는 첫 고객. 접수부터 결과까지 전 과정을 빠르게 검증한다.", en: "First customers who give honest feedback freely. Validate the full flow from intake to result fast.")), BUSoftOpenTrialType(label: BULoc(ko: "동네 첫 방문자", en: "Local first-timers"), desc: BULoc(ko: "전단·플레이스 보고 찾아온 실제 잠재 단골. 초기 응대와 가격 반응을 본다.", en: "Real potential regulars who came via flyers or Place. Watch first-contact handling and price reactions.")), BUSoftOpenTrialType(label: BULoc(ko: "체험·할인 고객", en: "Trial / discount customers"), desc: BULoc(ko: "오픈 할인으로 유치한 고객. 작업 난이도와 소요시간을 실측한다.", en: "Customers drawn by an opening discount. Measure real job difficulty and turnaround time.")), BUSoftOpenTrialType(label: BULoc(ko: "까다로운 케이스", en: "Tricky cases"), desc: BULoc(ko: "어려운 의뢰를 일부러 받아 한계와 추가요금 기준을 미리 세운다.", en: "Take a few hard jobs on purpose to find your limits and set extra-charge rules in advance."))],
      page1Steps: [BUSoftOpenStep(title: BULoc(ko: "시범 고객 5~10명 확보", en: "Line up 5-10 pilot customers"), detail: BULoc(ko: "지인·동네 첫 방문자·체험 할인 고객을 섞어 다양한 의뢰 유형을 받는다. 한 번에 몰지 말고 며칠에 분산해 동선을 점검한다.", en: "Mix friends, local first-timers, and trial-discount customers to cover varied job types. Spread them over several days, not all at once, to test your workflow.")), BUSoftOpenStep(title: BULoc(ko: "접수~견적~결과 전 과정 리허설", en: "Rehearse intake to quote to result"), detail: BULoc(ko: "의뢰 접수, 견적 안내, 작업, 인수까지 실제로 한 바퀴 돌려본다. 막히는 지점과 소요시간을 기록한다.", en: "Run one real loop: take the request, quote it, do the work, hand it back. Note bottlenecks and how long each takes.")), BUSoftOpenStep(title: BULoc(ko: "오픈 할인·체험가 고지", en: "Announce opening discount / trial price"), detail: BULoc(ko: "플레이스·전단·단톡방에 시범기간 할인을 알린다. 정상가 대비 할인폭과 종료일을 명확히 표시한다.", en: "Post the trial-period discount on Place, flyers, and local chats. State the discount vs. normal price and an end date clearly."))],
      feedbackAxes: [BUSoftOpenItem(label: BULoc(ko: "결과 만족도", en: "Result satisfaction"), detail: BULoc(ko: "수선·수리·청소 결과가 고객 기대에 맞았는가. 재작업·클레임 발생 여부를 본다.", en: "Did the alteration, repair, or cleaning result meet expectations? Track rework and complaints.")), BUSoftOpenItem(label: BULoc(ko: "견적 정확도", en: "Quote accuracy"), detail: BULoc(ko: "고지한 가격·소요시간이 실제와 맞았는가. 추가요금 안내가 사전에 명확했는가.", en: "Did the quoted price and time match reality? Were extra charges explained up front?")), BUSoftOpenItem(label: BULoc(ko: "응대·소통", en: "Service & communication"), detail: BULoc(ko: "접수 친절도, 진행 상황 공유, 완료 알림이 매끄러웠는가.", en: "Was intake friendly, progress shared, and completion notified smoothly?")), BUSoftOpenItem(label: BULoc(ko: "작업 시간·동선", en: "Turnaround & workflow"), detail: BULoc(ko: "실제 작업 시간이 예상과 맞았는가. 도구·부품·동선에서 낭비가 없었는가.", en: "Did actual work time match the estimate? Any wasted motion in tools, parts, or layout?"))],
      finalPrep: [BUSoftOpenItem(label: BULoc(ko: "부품·소모품 재고 확보", en: "Stock parts & consumables"), detail: BULoc(ko: "자주 쓰는 부품·실·세제·토너 등 소모품을 본오픈 물량으로 채우고 발주처를 확정한다.", en: "Fill consumables (common parts, thread, detergent, toner) to opening volume and lock in suppliers.")), BUSoftOpenItem(label: BULoc(ko: "장비·도구 최종 점검", en: "Final equipment & tool check"), detail: BULoc(ko: "기기 시운전, 도구 정비·교정을 마치고 고장 시 대체·수리 연락처를 준비한다.", en: "Test-run machines, service and calibrate tools, and keep backup/repair contacts ready for breakdowns.")), BUSoftOpenItem(label: BULoc(ko: "가격표·견적 기준 확정", en: "Finalize price list & quote rules"), detail: BULoc(ko: "시범기간 데이터로 정상 가격표와 추가요금 기준을 확정해 게시한다.", en: "Use trial-period data to finalize and post the normal price list and extra-charge rules.")), BUSoftOpenItem(label: BULoc(ko: "예약·접수 시스템 정비", en: "Set up booking & intake"), detail: BULoc(ko: "전화·플레이스·앱 예약 경로를 정리하고 접수표·인수증 양식을 갖춘다.", en: "Organize phone, Place, and app booking channels; prepare intake slips and receipt forms.")), BUSoftOpenItem(label: BULoc(ko: "본오픈 홍보·플레이스 등록", en: "Promote opening & register Place"), detail: BULoc(ko: "네이버 플레이스 정보·사진·영업시간을 완성하고 오픈 이벤트를 고지한다.", en: "Complete Naver Place info, photos, and hours; announce the opening event."))]),
    "space-rental": BUSoftOpenContent(
      softOpenMeaning: BULoc(ko: "공간대여 소프트오픈은 본격 예약 오픈 전에 지인·체험 이용자에게 무료 또는 할인 시범 대관을 열어 실제 사용 흐름(예약→입실→이용→퇴실·청소)을 검증하는 단계다. 공간 동선·시설·예약 시스템의 문제를 첫 이용자 관찰로 잡아낸다.", en: "For space rentals, a soft open means offering free or discounted trial bookings to friends and test guests before full reservation launch, validating the real flow (book to check-in to use to check-out and cleaning). You catch flaws in layout, facilities, and the booking system by observing first users."), page1Label: BULoc(ko: "1. 체험 예약", en: "1. Trial Booking"), pricingMode: "price", pricingAlt: nil,
      trialTypes: [BUSoftOpenTrialType(label: BULoc(ko: "지인·체험 이용자", en: "Friends and test guests"), desc: BULoc(ko: "실제 목적(촬영·모임·연습)대로 무료 시범 대관을 잡아 입실부터 퇴실까지 전 과정을 관찰한다.", en: "Book free trial slots for real purposes (shoot, gathering, practice) and observe the full flow from check-in to check-out.")), BUSoftOpenTrialType(label: BULoc(ko: "타깃 동호회·소모임", en: "Target clubs and small groups"), desc: BULoc(ko: "주 고객층(댄스팀·스터디·파티 모임 등)을 초대해 다인 동시 이용 시 동선·소음·정원 적정성을 점검한다.", en: "Invite core user groups (dance teams, study groups, parties) to test flow, noise, and capacity under multi-person use.")), BUSoftOpenTrialType(label: BULoc(ko: "할인 체험 예약자", en: "Discounted early bookers"), desc: BULoc(ko: "오픈 할인가로 첫 외부 예약을 받아 예약 시스템·결제·안내 메시지가 실제로 작동하는지 검증한다.", en: "Take first outside bookings at an opening discount to verify booking, payment, and guide messages work in practice.")), BUSoftOpenTrialType(label: BULoc(ko: "리뷰·사진 협조자", en: "Review and photo helpers"), desc: BULoc(ko: "이용 후 솔직한 후기와 공간 사진을 받아 OTA·플랫폼 상세페이지에 쓸 초기 콘텐츠를 확보한다.", en: "Collect honest reviews and space photos after use to seed listing content for OTA and platform pages."))],
      page1Steps: [BUSoftOpenStep(title: BULoc(ko: "체험 대관 슬롯 열기", en: "Open trial booking slots"), detail: BULoc(ko: "오픈 1~2주 전 무료·할인 시범 대관 시간대를 만들어 지인과 타깃 모임을 초대한다. 실제 예약 시스템으로 받아 흐름까지 테스트한다.", en: "1-2 weeks before launch, create free/discount trial slots and invite friends and target groups. Take them through the real booking system to test the flow.")), BUSoftOpenStep(title: BULoc(ko: "입실~퇴실 전 과정 관찰", en: "Observe the full check-in to check-out flow"), detail: BULoc(ko: "첫 이용자가 예약 안내대로 출입·이용·정리까지 막힘없이 하는지 옆에서 지켜보고, 헤매는 지점을 기록한다.", en: "Watch first users follow the booking guide through access, use, and tidy-up; note every point where they get stuck.")), BUSoftOpenStep(title: BULoc(ko: "이용 후 정리·청소 시간 측정", en: "Measure turnover and cleaning time"), detail: BULoc(ko: "한 팀이 나간 뒤 원상복구·청소·세팅에 걸리는 실제 시간을 재서 예약 간 간격(버퍼)을 정한다.", en: "Time how long reset, cleaning, and setup actually take after a group leaves, and set the buffer between bookings."))],
      feedbackAxes: [BUSoftOpenItem(label: BULoc(ko: "예약·입실 편의성", en: "Booking and access ease"), detail: BULoc(ko: "예약·결제·출입 안내가 헷갈리지 않았는지, 비대면 출입(도어록·QR)이 막힘없이 됐는지.", en: "Whether booking, payment, and access guides were clear, and contactless entry (smart lock/QR) worked smoothly.")), BUSoftOpenItem(label: BULoc(ko: "공간·시설 만족도", en: "Space and facility satisfaction"), detail: BULoc(ko: "조명·가구 배치·정원·장비 상태가 이용 목적에 맞았는지, 부족·고장 시설은 없었는지.", en: "Whether lighting, furniture layout, capacity, and equipment fit the purpose, and if anything was missing or broken.")), BUSoftOpenItem(label: BULoc(ko: "청결·정리 상태", en: "Cleanliness and reset state"), detail: BULoc(ko: "입실 시 깨끗했는지, 쓰레기·비품·화장실 청결이 기대 수준이었는지.", en: "Whether the space was clean on arrival and trash, supplies, and restroom met expectations.")), BUSoftOpenItem(label: BULoc(ko: "소음·방음", en: "Noise and soundproofing"), detail: BULoc(ko: "내부 소리가 외부·옆 호실로 새지 않는지, 외부 소음이 이용을 방해하지 않았는지(민원 폐업 1순위).", en: "Whether inside sound leaked out or to neighbors, and outside noise disrupted use (the top cause of forced closure)."))],
