    "pet-grooming": [BUSoftOpenDayCheck(id: "day-blade-clean", label: BULoc(ko: "클리퍼 날·가위 소독", en: "Disinfect clippers and scissors"), detail: BULoc(ko: "미용 도구를 견마다 소독·교체하고 날 상태를 점검해 피부 감염과 상처를 예방한다.", en: "Disinfect and swap grooming tools between pets and check blade condition to prevent skin infection and cuts.")), BUSoftOpenDayCheck(id: "day-bath-temp", label: BULoc(ko: "목욕 수온·샴푸 점검", en: "Check bath water temp and shampoo"), detail: BULoc(ko: "수온을 미온수로 맞추고 견종·피부에 맞는 샴푸를 준비해 화상·자극을 막는다.", en: "Set lukewarm water and prepare shampoo suited to breed and skin to avoid burns and irritation.")), BUSoftOpenDayCheck(id: "day-dryer", label: BULoc(ko: "드라이어 온도·소음 점검", en: "Check dryer heat and noise"), detail: BULoc(ko: "드라이어 온도와 소음을 점검하고 화상·청각 스트레스 없이 건조되는지 확인한다.", en: "Check dryer heat and noise and confirm drying without burns or sound stress.")), BUSoftOpenDayCheck(id: "day-pet-info", label: BULoc(ko: "반려견 정보·특이사항 접수", en: "Intake pet info and notes"), detail: BULoc(ko: "견종·나이·피부질환·예민 부위·물림 이력을 미리 확인해 안전하게 미용한다.", en: "Confirm breed, age, skin issues, sensitive spots, and bite history upfront for safe grooming.")), BUSoftOpenDayCheck(id: "day-stylist", label: BULoc(ko: "미용사 일정·숙련도 배정", en: "Assign stylist schedule and skill"), detail: BULoc(ko: "예약별 난이도에 맞게 미용사를 배정하고 작업 시간을 현실적으로 잡는다.", en: "Assign stylists to bookings by difficulty and set realistic working times."))],
    "pet-cafe": [BUSoftOpenDayCheck(id: "day-animal-health", label: BULoc(ko: "상주 동물 건강·접종 점검", en: "Check resident animal health and shots"), detail: BULoc(ko: "상주 반려동물의 컨디션·접종 상태를 확인하고 아픈 개체는 합사에서 제외한다.", en: "Check resident animals' condition and vaccination and pull any sick animal from the group.")), BUSoftOpenDayCheck(id: "day-vent-deodor", label: BULoc(ko: "환기·탈취 가동", en: "Run ventilation and deodorizing"), detail: BULoc(ko: "환기 설비와 탈취제를 가동해 동물 냄새가 손님이 거북하지 않은 수준인지 확인한다.", en: "Run ventilation and deodorizer and confirm animal odor stays at a level guests find acceptable.")), BUSoftOpenDayCheck(id: "day-floor-clean", label: BULoc(ko: "바닥·배변 즉시 청소", en: "Clean floors and waste immediately"), detail: BULoc(ko: "배변을 즉시 처리하고 바닥을 소독해 위생과 미끄럼 사고를 동시에 막는다.", en: "Clear waste immediately and disinfect floors to prevent both hygiene issues and slips.")), BUSoftOpenDayCheck(id: "day-water-bowl", label: BULoc(ko: "급수기·식기 청결", en: "Clean water and food bowls"), detail: BULoc(ko: "급수기·식기를 세척·소독하고 신선한 물을 채워 교차 감염을 줄인다.", en: "Wash and disinfect water and food bowls and refill fresh water to reduce cross-infection.")), BUSoftOpenDayCheck(id: "day-customer-rules", label: BULoc(ko: "이용 규칙·펫티켓 안내", en: "Brief usage rules and pet etiquette"), detail: BULoc(ko: "입장 시 접종 확인·간식 반입·합사 규칙을 안내해 동물 간 다툼을 예방한다.", en: "At entry, brief vaccination checks, treat rules, and grouping rules to prevent animal conflicts."))],
    "pet-hotel": [BUSoftOpenDayCheck(id: "day-animal-checkin", label: BULoc(ko: "입실 체크인·건강 확인", en: "Check-in and health verification"), detail: BULoc(ko: "입실 시 접종·기저질환·특이행동을 확인하고 사진·동의서로 상태를 기록한다.", en: "At check-in confirm vaccination, conditions, and behavior, and record state with photos and consent.")), BUSoftOpenDayCheck(id: "day-room-clean", label: BULoc(ko: "객실·켄넬 소독", en: "Disinfect rooms and kennels"), detail: BULoc(ko: "객실·켄넬을 개체별로 소독하고 탈출·끼임 위험이 없는지 점검한다.", en: "Disinfect rooms and kennels per animal and check for escape or entrapment risks.")), BUSoftOpenDayCheck(id: "day-feeding", label: BULoc(ko: "급식·급약 일정 관리", en: "Manage feeding and medication"), detail: BULoc(ko: "개체별 사료·급약 시간과 양을 일지로 관리해 누락·과급을 막는다.", en: "Track each animal's food and medication times and amounts in a log to avoid misses or overfeeding.")), BUSoftOpenDayCheck(id: "day-walk-schedule", label: BULoc(ko: "산책·배변 스케줄", en: "Walk and toilet schedule"), detail: BULoc(ko: "개체별 산책·배변 일정을 정해 스트레스를 줄이고 보호자에게 사진으로 공유한다.", en: "Set per-animal walk and toilet schedules to reduce stress and share photos with owners.")), BUSoftOpenDayCheck(id: "day-emergency-vet", label: BULoc(ko: "응급 동물병원 연계 확인", en: "Confirm emergency vet link"), detail: BULoc(ko: "야간·응급 시 연락 가능한 동물병원과 이송 절차를 미리 확정해 둔다.", en: "Pre-confirm a night and emergency vet contact and the transport procedure."))],
    "pet-training-school": [BUSoftOpenDayCheck(id: "day-trainer", label: BULoc(ko: "훈련사 배정·자격 확인", en: "Assign trainer and verify cert"), detail: BULoc(ko: "수업별 훈련사를 배정하고 자격·경력을 확인해 보호자 신뢰를 확보한다.", en: "Assign trainers per class and verify certification and experience to secure owner trust.")), BUSoftOpenDayCheck(id: "day-equipment", label: BULoc(ko: "훈련 기구·간식 점검", en: "Check training gear and treats"), detail: BULoc(ko: "리드줄·어질리티 기구·보상 간식을 점검해 안전하고 끊김 없이 수업을 진행한다.", en: "Check leashes, agility gear, and reward treats for safe, uninterrupted classes.")), BUSoftOpenDayCheck(id: "day-floor-safe", label: BULoc(ko: "바닥·울타리 안전 점검", en: "Check floor and fence safety"), detail: BULoc(ko: "미끄럼·탈출·부상 위험을 점검해 훈련 중 사고를 예방한다.", en: "Check slip, escape, and injury risks to prevent incidents during training.")), BUSoftOpenDayCheck(id: "day-class-roster", label: BULoc(ko: "수강 명단·견 상태 확인", en: "Confirm roster and pet condition"), detail: BULoc(ko: "수강 견의 접종·성향·문제행동을 사전 확인하고 그룹 구성을 안전하게 짠다.", en: "Pre-confirm enrolled dogs' vaccination, temperament, and issues and arrange safe groupings.")), BUSoftOpenDayCheck(id: "day-emergency-vet", label: BULoc(ko: "응급 대응·동물병원 연계", en: "Emergency response and vet link"), detail: BULoc(ko: "훈련 중 부상·발작 등 응급 상황 대응 절차와 동물병원 연락처를 비치한다.", en: "Post the emergency procedure and vet contact for injuries or seizures during training."))],
    "convenience-small": [BUSoftOpenDayCheck(id: "day-stock-replenish", label: BULoc(ko: "결품·보충 발주 점검", en: "Stock-out & replenishment order check"), detail: BULoc(ko: "빠르게 빠지는 품목의 결품 여부를 확인하고, 본사 자동발주에만 의존하지 말고 매장 수요에 맞춰 추가 발주합니다.", en: "Check for stock-outs on fast-moving items and place extra orders to match store demand rather than relying only on HQ auto-ordering.")), BUSoftOpenDayCheck(id: "day-expiry", label: BULoc(ko: "유통기한 선입선출", en: "Expiry FIFO rotation"), detail: BULoc(ko: "삼각김밥·샌드위치 등 신선식품의 소비기한을 확인하고, 임박 상품을 앞으로 빼는 선입선출 진열을 점검합니다.", en: "Check use-by dates on fresh items like rice balls and sandwiches, and verify FIFO placement with near-expiry items at the front.")), BUSoftOpenDayCheck(id: "day-cigarette", label: BULoc(ko: "담배·성인인증 절차", en: "Tobacco & age verification"), detail: BULoc(ko: "담배 재고·진열 위치와 연령 확인 절차, 성인인증 키오스크·POS 연동이 정상인지 점검합니다.", en: "Check tobacco stock and placement, age-verification procedure, and that ID-check kiosk/POS integration works.")), BUSoftOpenDayCheck(id: "day-cctv-record", label: BULoc(ko: "CCTV 녹화 확인", en: "CCTV recording check"), detail: BULoc(ko: "매장 내·외부 CCTV가 사각지대 없이 녹화·저장되는지, 카운터·출입구가 잘 잡히는지 확인합니다.", en: "Verify interior/exterior CCTV records and stores without blind spots, with the counter and entrance well covered.")), BUSoftOpenDayCheck(id: "day-pos-speed", label: BULoc(ko: "POS 계산 속도", en: "POS checkout speed"), detail: BULoc(ko: "바코드 스캔·결제·교통카드 충전·택배 처리가 빠르게 되는지, 혼잡 시간대 대기 흐름을 점검합니다.", en: "Check that barcode scan, payment, transit-card top-up, and parcel handling are fast, and review queue flow at peak times."))],
    "lifestyle-goods": [BUSoftOpenDayCheck(id: "day-display-curate", label: BULoc(ko: "진열 큐레이션", en: "Display curation"), detail: BULoc(ko: "콘셉트에 맞�게 컬러·테마별로 묶어 진열했는지, 손님이 멈춰 보는 매대와 그냥 지나치는 매대를 관찰합니다.", en: "Check that items are grouped by color/theme to fit the concept, and observe which displays make shoppers stop versus pass by.")), BUSoftOpenDayCheck(id: "day-photo-spot", label: BULoc(ko: "포토존 점검", en: "Photo-spot check"), detail: BULoc(ko: "손님이 사진 찍고 싶어 하는 포토존이 잘 작동하는지, 조명·배경·해시태그 안내가 준비됐는지 확인합니다.", en: "Check the photo spot draws shoppers to take pictures, with good lighting, backdrop, and hashtag guidance ready.")), BUSoftOpenDayCheck(id: "day-stock-rotation", label: BULoc(ko: "잘 나가는 품목 보충", en: "Best-seller restock"), detail: BULoc(ko: "시범 운영에서 잘 팔린 소품을 파악해 매대 위치를 조정하고 결품 없이 보충합니다.", en: "Identify which goods sold well during the trial, adjust their shelf placement, and restock to avoid stock-outs.")), BUSoftOpenDayCheck(id: "day-package", label: BULoc(ko: "포장·선물 패키지", en: "Packaging & gift wrap"), detail: BULoc(ko: "선물용 포장재·쇼핑백 재고와 포장 속도를 점검하고, 손님이 만족하는 마무리인지 확인합니다.", en: "Check gift-wrap and shopping-bag stock and wrapping speed, and confirm the finish satisfies shoppers.")), BUSoftOpenDayCheck(id: "day-music-light", label: BULoc(ko: "음악·조명 분위기", en: "Music & lighting mood"), detail: BULoc(ko: "매장 음악 볼륨과 조명 밝기·색온도가 콘셉트와 맞는지, 손님 체류 분위기를 관찰합니다.", en: "Check music volume and lighting brightness/color match the concept, and observe the dwell-time atmosphere."))],
    "beauty-supplies": [BUSoftOpenDayCheck(id: "day-tester", label: BULoc(ko: "테스터 위생 운영", en: "Tester hygiene operation"), detail: BULoc(ko: "테스터가 위생적으로 비치됐는지, 일회용 퍼프·면봉·소독제가 준비됐는지, 손님이 부담 없이 써보는지 관찰합니다.", en: "Check testers are set out hygienically with disposable puffs, swabs, and sanitizer, and observe whether shoppers try them comfortably.")), BUSoftOpenDayCheck(id: "day-product-expiry", label: BULoc(ko: "화장품 유통기한·개봉기한", en: "Cosmetics expiry & PAO"), detail: BULoc(ko: "제품별 유통기한과 개봉 후 사용기한(PAO)을 확인하고, 임박 상품을 분리·전진 진열합니다.", en: "Check each product's expiry and period-after-opening (PAO), and separate/front near-expiry items.")), BUSoftOpenDayCheck(id: "day-staff-knowledge", label: BULoc(ko: "직원 제품 지식", en: "Staff product knowledge"), detail: BULoc(ko: "피부 고민별 제품 추천·성분·사용법 설명을 직원이 매끄럽게 하는지 시범 응대로 점검합니다.", en: "Through trial interactions, check staff can smoothly recommend products by skin concern and explain ingredients and usage.")), BUSoftOpenDayCheck(id: "day-stock-bestseller", label: BULoc(ko: "인기 품목 재고", en: "Best-seller stock"), detail: BULoc(ko: "수요 높은 인기·신상 품목의 재고와 컬러·호수 구색이 충분한지 확인하고 보충합니다.", en: "Verify stock and shade/size assortment for high-demand and new items are sufficient, and restock.")), BUSoftOpenDayCheck(id: "day-display", label: BULoc(ko: "카테고리 진열", en: "Category display"), detail: BULoc(ko: "스킨케어·메이크업·헤어·바디 등 카테고리별 진열이 직관적인지, 가격표가 명확한지 점검합니다.", en: "Check category displays (skincare, makeup, hair, body) are intuitive and price tags are clear."))],
    "fashion-accessories": [BUSoftOpenDayCheck(id: "day-display-rotate", label: BULoc(ko: "진열 회전·연출", en: "Display rotation & styling"), detail: BULoc(ko: "신상·인기 액세서리를 눈에 띄는 매대에 배치하고, 손님 반응에 따라 진열을 바꿔봅니다.", en: "Place new and popular accessories on eye-catching displays and rotate styling based on shopper reactions.")), BUSoftOpenDayCheck(id: "day-stock-trend", label: BULoc(ko: "트렌드 품목 재고", en: "Trend item stock"), detail: BULoc(ko: "현재 유행하는 디자인·컬러 품목의 재고와 사이즈·수량이 충분한지 확인합니다.", en: "Check stock, sizes, and quantities are sufficient for currently trending designs and colors.")), BUSoftOpenDayCheck(id: "day-tag-price", label: BULoc(ko: "가격표·택 부착", en: "Price tags & labels"), detail: BULoc(ko: "모든 품목에 가격표·택이 빠짐없이 붙었는지, 도난 방지 택 부착이 정상인지 점검합니다.", en: "Verify every item has a price tag/label and that anti-theft tags are properly attached.")), BUSoftOpenDayCheck(id: "day-mirror", label: BULoc(ko: "거울·착용 공간", en: "Mirrors & try-on space"), detail: BULoc(ko: "거울 위치·조명이 착용 모습을 잘 비추는지, 손님이 편하게 착용해보는지 관찰합니다.", en: "Check mirror placement and lighting flatter try-ons, and observe whether shoppers try items on comfortably.")), BUSoftOpenDayCheck(id: "day-ig-content", label: BULoc(ko: "인스타 콘텐츠 촬영", en: "Instagram content shoot"), detail: BULoc(ko: "신상·매장 분위기를 SNS용으로 촬영하고, 포토존·해시태그 안내가 노출 유도에 효과적인지 확인합니다.", en: "Shoot new items and store mood for SNS, and check the photo spot and hashtag guidance drive exposure effectively."))],
    "health-food-store": [BUSoftOpenDayCheck(id: "day-product-expiry", label: BULoc(ko: "유통·소비기한 점검", en: "Expiry & use-by check"), detail: BULoc(ko: "건강기능식품의 제형별 유통·소비기한을 확인하고, 임박 상품을 전진 진열·분리합니다.", en: "Check expiry/use-by dates by formulation for health supplements, and front/separate near-expiry items.")), BUSoftOpenDayCheck(id: "day-temp-storage", label: BULoc(ko: "보관 온도·환경", en: "Storage temperature & environment"), detail: BULoc(ko: "직사광선·습기를 피한 실온(1~30도) 보관 원칙을 지키는지, 냉장 보관 품목 온도가 맞는지 점검합니다.", en: "Verify room-temperature (1–30°C) storage away from direct sun and moisture, and that refrigerated items are at the right temperature.")), BUSoftOpenDayCheck(id: "day-staff-knowledge", label: BULoc(ko: "직원 상담 지식", en: "Staff consultation knowledge"), detail: BULoc(ko: "목적별 제품 추천·복용법·주의사항을 직원이 정확히 안내하는지, 과장·의학적 효능 단정 표현을 피하는지 점검합니다.", en: "Check staff accurately guide product choice, dosage, and cautions by purpose, avoiding exaggerated or medical-efficacy claims.")), BUSoftOpenDayCheck(id: "day-allergen", label: BULoc(ko: "알레르기 성분 표시", en: "Allergen labeling"), detail: BULoc(ko: "알레르기 유발성분 표시가 잘 보이는지, 손님 문의 시 성분을 즉시 확인·안내할 수 있는지 점검합니다.", en: "Verify allergen labels are visible and that staff can immediately check and explain ingredients when asked.")), BUSoftOpenDayCheck(id: "day-cert-display", label: BULoc(ko: "인증·라벨 게시", en: "Certification & label display"), detail: BULoc(ko: "건강기능식품 인증마크·영업신고증 등 필수 표시·게시물이 제자리에 부착됐는지 확인합니다.", en: "Verify the health-functional-food certification mark, business registration, and other required notices are posted in place."))],
    "pet-supplies": [BUSoftOpenDayCheck(id: "day-animal-health", label: BULoc(ko: "분양동물 건강 점검", en: "Live-animal health check"), detail: BULoc(ko: "매장 내 분양·전시 동물이 있다면 활력·식이·배변 상태를 점검하고 이상 징후를 기록합니다.", en: "If the store displays/sells live animals, check their vitality, feeding, and elimination, recording any abnormal signs.")), BUSoftOpenDayCheck(id: "day-cage-clean", label: BULoc(ko: "케이지·전시공간 위생", en: "Cage & display hygiene"), detail: BULoc(ko: "케이지·수조·전시공간을 청소·소독하고, 바닥재·급수기 상태가 위생적인지 점검합니다.", en: "Clean and disinfect cages, tanks, and display areas, and check bedding and water dispensers are hygienic.")), BUSoftOpenDayCheck(id: "day-food-expiry", label: BULoc(ko: "사료·간식 유통기한", en: "Pet food & treat expiry"), detail: BULoc(ko: "사료·간식의 유통기한을 확인하고 선입선출로 진열하며, 개봉·보관 상태를 점검합니다.", en: "Check pet food and treat expiry dates, display FIFO, and verify opening and storage conditions.")), BUSoftOpenDayCheck(id: "day-vent-deodor", label: BULoc(ko: "환기·탈취 관리", en: "Ventilation & odor control"), detail: BULoc(ko: "매장 냄새를 환기·탈취로 관리하고, 손님이 들어왔을 때 불쾌한 냄새가 없는지 확인합니다.", en: "Manage store odor with ventilation and deodorizing, and confirm there's no unpleasant smell when shoppers enter.")), BUSoftOpenDayCheck(id: "day-grooming-tool", label: BULoc(ko: "미용·용품 시연 점검", en: "Grooming & supply demo check"), detail: BULoc(ko: "미용 도구·용품의 상태와 사용법 안내를 점검하고, 손님이 용품을 직접 살펴볼 수 있게 진열합니다.", en: "Check grooming tools and supplies' condition and usage guidance, and display goods so shoppers can examine them hands-on."))],
    "cleaning-service": [BUSoftOpenDayCheck(id: "day-staff-schedule", label: BULoc(ko: "인력·배차 스케줄 확인", en: "Confirm staff & dispatch schedule"), detail: BULoc(ko: "당일 청소 건별 담당자와 이동 동선을 배정하고 지각·결원 대비 백업을 둔다.", en: "Assign a worker and travel route per job; keep backup ready for lateness or no-shows.")), BUSoftOpenDayCheck(id: "day-supply-stock", label: BULoc(ko: "청소 약품·소모품 재고", en: "Cleaning supplies stock"), detail: BULoc(ko: "세제·장갑·걸레·비닐 등 당일 소모품을 채우고 부족분을 보충 발주한다.", en: "Refill daily consumables (detergent, gloves, cloths, bags) and reorder shortages.")), BUSoftOpenDayCheck(id: "day-customer-info", label: BULoc(ko: "고객 주소·요청사항 확인", en: "Verify address & requests"), detail: BULoc(ko: "방문지 주소, 출입방법, 특별 요청(반려동물·금지구역)을 사전 확인한다.", en: "Check each address, entry method, and special requests (pets, off-limit areas) beforehand.")), BUSoftOpenDayCheck(id: "day-photo-report", label: BULoc(ko: "전후 사진·작업 리포트", en: "Before/after photos & report"), detail: BULoc(ko: "작업 전후 사진을 찍어 고객에게 결과를 공유하고 분쟁을 예방한다.", en: "Take before/after photos to share results and prevent disputes.")), BUSoftOpenDayCheck(id: "day-emergency", label: BULoc(ko: "파손·민원 대응 준비", en: "Damage & complaint response"), detail: BULoc(ko: "물건 파손·민원 발생 시 배상·재방문 절차와 연락 라인을 정해둔다.", en: "Set procedures and a contact line for damage, complaints, and re-visits."))],
