    "guesthouse": [BUSoftOpenDayCheck(id: "day-checkin-out", label: BULoc(ko: "체크인·체크아웃 동선", en: "Check-in/out flow"), detail: BULoc(ko: "예약 안내대로 입실·키 수령·퇴실이 막힘없는지, 셀프 체크인 시 출입 안내가 명확한지 점검.", en: "Verify check-in, key handover, and check-out follow the guide smoothly; self check-in access instructions are clear.")), BUSoftOpenDayCheck(id: "day-linen", label: BULoc(ko: "침구·수건 세탁·재고", en: "Linen and towel stock"), detail: BULoc(ko: "객실별 깨끗한 침구·수건 세트와 여유분이 확보됐는지, 세탁 회전이 가능한지 확인.", en: "Confirm clean linen and towel sets per room plus spares, and that laundry turnover keeps up.")), BUSoftOpenDayCheck(id: "day-amenity-stock", label: BULoc(ko: "어메니티·소모품 재고", en: "Amenity and consumable stock"), detail: BULoc(ko: "샴푸·휴지·생수·일회용품 등 객실·공용 소모품을 본오픈 물량으로 채움.", en: "Restock room and shared amenities (shampoo, tissue, water, disposables) to launch quantities.")), BUSoftOpenDayCheck(id: "day-clean", label: BULoc(ko: "객실·공용공간 청결", en: "Room and common area cleanliness"), detail: BULoc(ko: "입실 전 객실·화장실·주방·라운지 청소 상태가 기대 수준인지 최종 확인.", en: "Final check that rooms, restrooms, kitchen, and lounge meet cleanliness expectations before guests.")), BUSoftOpenDayCheck(id: "day-fire-safety", label: BULoc(ko: "소방·안전 설비", en: "Fire and safety equipment"), detail: BULoc(ko: "소화기·단독경보형감지기·비상구 안내가 법적 기준대로 설치·작동하는지 점검.", en: "Confirm fire extinguishers, smoke alarms, and exit signage meet legal standards and work."))],
