  public static func archetype(subIndustryId: String?, categoryId: String?) -> String {
    if let s = subIndustryId, let a = subArchetype[s] { return a }
    if let c = categoryId, let a = catFallback[c] { return a }
    return "dine-in" }
  public static func content(subIndustryId: String?, categoryId: String?) -> BUSoftOpenContent {
    archetypes[archetype(subIndustryId: subIndustryId, categoryId: categoryId)] ?? archetypes["dine-in"]! }
  public static func dayChecks(subIndustryId: String?) -> [BUSoftOpenDayCheck] {
    guard let s = subIndustryId else { return [] }; return dayChecks[s] ?? [] }
}
